{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative & Whole-Person Care</title>
  <meta name="description" content="Practical, evidence-minded holistic medicine focused on lifestyle, nutrition, stress resilience and restorative therapies. VIP Day and ongoing plans available." />
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-clinic">
  <header class="topbar">
    <div class="container topbar-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="nav">
        <a href="/services.html">What We Do</a>
        <a href="/approach.html">Care Path</a>
        <a href="/about.html">Meet</a>
        <a href="/pricing.html" class="muted">Fees</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button id="navToggle" class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1 class="eyebrow">Practical integrative care in {{CITY}}, {{STATE}}</h1>
          <h2>{{TAGLINE}}</h2>
          <p class="lede">Whole-person medicine that blends nutrition, lifestyle, targeted testing and restorative therapies to help you feel like yourself again. Ideal for adults seeking focused, expert guidance without unrealistic promises.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/approach.html">How we work</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card">
            <h3>Quick connect</h3>
            <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
            <a class="btn small" href="/book.html">Book a consult</a>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section id="story" class="section story">
      <div class="container">
        <div class="split">
          <div>
            <h3>Why this practice exists</h3>
            <p>After years in conventional care, {{PRACTITIONER_NAME}}, {{CREDENTIALS}}, saw that many patients needed a coordinated, practical plan that addresses sleep, digestion, stress and energy together. Our approach is grounded in evidence-informed tools, individualized planning and measurable goals.</p>
            <p class="muted">We do not promise cures. We provide education, supportive therapies, and follow-up to help you improve function and quality of life.</p>
          </div>
          <aside class="profile">
            <div class="avatar" aria-hidden="true">{{PRACTITIONER_NAME}}</div>
            <p><strong>{{PRACTITIONER_NAME}}, {{CREDENTIALS}}</strong><br>Founder & Lead Clinician</p>
            <a class="link" href="/about.html">Read full bio</a>
          </aside>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section id="framework" class="section framework">
      <div class="container">
        <h3>Our care framework — a simple roadmap</h3>
        <div class="cards">
          <div class="card small">
            <h4>Intake & listening</h4>
            <p>Comprehensive history, symptom mapping, priorities and a practical review of current habits and meds.</p>
          </div>
          <div class="card small">
            <h4>Personalized plan</h4>
            <p>Actionable steps across sleep, stress, movement and nutrition with measurable short-term targets.</p>
          </div>
          <div class="card small">
            <h4>Optional targeted labs</h4>
            <p>Educational testing (when relevant) such as nutrient panels, thyroid, and functional metabolic markers to clarify drivers.</p>
          </div>
          <div class="card small">
            <h4>Follow-ups & revisions</h4>
            <p>Periodic reassessment to adjust therapies. We prioritize sustainable interventions you can maintain.</p>
          </div>
        </div>
        <p class="muted small">All testing and interventions are discussed collaboratively. We never promote unnecessary or experimental procedures without clear rationale.</p>
      </div>
    </section>

    <!-- OFFERS -->
    <section id="offers" class="section offers">
      <div class="container">
        <h3>Signature offerings</h3>
        <div class="offers-grid">
          <div class="offer">
            <h4>VIP Day — Focused Transformation</h4>
            <p>A concentrated 6-hour intensive visit for busy adults who want a deep reboot: comprehensive intake, immediate plan, and diet/movement blueprint to take home.</p>
            <p class="muted small">Includes written plan and phone follow-up. Excellent as a single decisive step or part of ongoing care.</p>
            <a class="btn" href="/book.html">Reserve a VIP Day</a>
          </div>
          <div class="offer">
            <h4>Short Course — 3 visits</h4>
            <p>Practical progression over three visits to build habits, troubleshoot labs and solidify routine changes.</p>
            <a class="btn ghost" href="/pricing.html">See pricing</a>
          </div>
          <div class="offer">
            <h4>Monthly support</h4>
            <p>Ongoing coaching and monthly check-ins for patients who benefit from continuity and accountability.</p>
            <a class="btn" href="/contact.html">Inquire</a>
          </div>
        </div>
      </div>
    </section>

    <!-- PRICING TEASER -->
    <section id="pricing" class="section pricing">
      <div class="container">
        <h3>Transparent fees</h3>
        <p>We publish clear pricing and offer both one-time VIP Days and multi-visit packages. Insurance may not cover integrative services; ask about superbills.</p>
        <a class="btn" href="/pricing.html">Full fee schedule</a>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section id="testimonials" class="section testimonials">
      <div class="container">
        <h3>Patient perspectives</h3>
        <div class="test-grid">
          <blockquote class="testimonial">
            <p>"I finally have a clear plan that fits my schedule. The VIP Day gave me momentum—no fluff, just tools."</p>
            <footer>— A. from {{CITY}}</footer>
          </blockquote>
          <blockquote class="testimonial">
            <p>"Practical steps for sleep and energy. Each follow-up was a focused troubleshooting session."</p>
            <footer>— R., Satisfied patient</footer>
          </blockquote>
        </div>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section class="section cta stripe">
      <div class="container">
        <div class="cta-inner">
          <div>
            <h3>Ready to build a practical health plan?</h3>
            <p>Start with a focused visit or schedule a VIP Day to fast-track progress. We'll work together to create sustainable changes.</p>
          </div>
          <div>
            <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="link muted" href="/contact.html">Questions? Email {{EMAIL}}</a>
          </div>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">Integrative, evidence-minded care in {{CITY}}, {{STATE}}.</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav class="foot-nav">
        <a href="/services.html">Services</a>
        <a href="/conditions.html">Conditions</a>
        <a href="/about.html">About</a>
        <a href="/book.html">Book</a>
      </nav>
    </div>
    <div class="legal"><small>We do not offer guaranteed cures. Information provided is educational and not a substitute for individualized medical advice.</small></div>
  </footer>

</body>
</html>"} 
