{"path":"assets/css/styles.css","content":"/* Clinic Modern — CSS only, no external assets */
:root{
  --bg:#fbfefc;
  --primary:#0b6b52;
  --accent:#7dd3c1;
  --muted:#6b7280;
  --card:#ffffff;
  --glass: rgba(255,255,255,0.7);
  --shadow: 0 8px 24px rgba(11,107,82,0.08);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:linear-gradient(180deg,var(--bg),#eef6f3); color:#122018; -webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:24px}
.topbar{background:linear-gradient(90deg, rgba(7,66,55,0.04), rgba(125,211,193,0.03));backdrop-filter: blur(6px);border-bottom:1px solid rgba(11,107,82,0.04)}
.topbar-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;letter-spacing:0.2px;color:var(--primary);text-decoration:none}
.nav{display:flex;gap:18px;align-items:center}
.nav a{color:#153a2f;text-decoration:none;padding:8px 6px}
.nav a.cta{background:var(--primary);color:white;padding:8px 12px;border-radius:8px}
.nav a.muted{color:var(--muted)}
.nav-toggle{display:none;background:none;border:0;font-size:20px}

.hero{padding:56px 0;background-repeat:no-repeat;background-size:cover}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:center}
.eyebrow{font-size:14px;color:var(--muted);margin:0 0 8px}
h2{font-size:32px;margin:0 0 12px;color:var(--primary)}
.lede{font-size:16px;color:#274437;line-height:1.45}
.hero-card .card{background:linear-gradient(180deg,var(--card),#fbfffb);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;color:var(--primary);border:1px solid rgba(11,107,82,0.08);background:white}
.btn.primary{background:var(--primary);color:white;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(11,107,82,0.08)}
.btn.small{padding:8px 10px;font-size:13px}

.section{padding:36px 0}
.story .split{display:flex;gap:24px;align-items:flex-start}
.profile{width:240px;text-align:center}
.avatar{background:linear-gradient(135deg,var(--accent),#bdebe0);height:96px;width:96px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;color:#063227;margin:0 auto 12px}
.muted{color:var(--muted)}

.framework .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:18px}
.card.small{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 18px rgba(11,107,82,0.04)}

.offers-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.offer{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--card));padding:18px;border-radius:12px;box-shadow:var(--shadow)}

.pricing .btn{margin-top:12px}

.testimonials .test-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.testimonial{background:linear-gradient(180deg,#ffffff,#f8fffb);padding:16px;border-radius:8px;border-left:4px solid var(--accent)}
.testimonial footer{font-size:13px;color:var(--muted);margin-top:8px}

.cta.stripe{background:linear-gradient(90deg, rgba(11,107,82,0.06), rgba(125,211,193,0.03));border-radius:10px}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.btn.large{padding:14px 20px;border-radius:10px}

.site-footer{padding:28px 0 48px;border-top:1px solid rgba(11,107,82,0.04);margin-top:36px}
.footer-grid{display:flex;justify-content:space-between;align-items:flex-start}
.foot-nav a{display:block;color:var(--muted);text-decoration:none;margin-bottom:6px}
.legal{text-align:center;color:var(--muted);margin-top:18px}

/* Responsive */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .framework .cards{grid-template-columns:repeat(2,1fr)}
  .offers-grid{grid-template-columns:1fr}
  .testimonials .test-grid{grid-template-columns:1fr}
  .topbar-inner{padding:10px}
  .nav{display:none;position:absolute;right:16px;top:64px;background:var(--card);flex-direction:column;padding:12px;border-radius:8px;box-shadow:var(--shadow)}
  .nav-toggle{display:block}
}

/* Use embedded SVG pattern as background with subtle overlay */
.hero{background-color:linear-gradient(180deg,var(--bg),#eef6f3)}
"}
{"path":"assets/js/main.js","content":"(function(){
  document.addEventListener('DOMContentLoaded', function(){
    var nav = document.getElementById('nav');
    var toggle = document.getElementById('navToggle');
    if(toggle){
      toggle.addEventListener('click', function(){
        if(nav.style.display==='flex' || nav.style.display==='block'){
          nav.style.display='none';
        } else {
          nav.style.display='block';
        }
      });
    }

    // Smooth internal links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click', function(e){
        var id = a.getAttribute('href').slice(1);
        var el = document.getElementById(id);
        if(el){
          e.preventDefault();
          el.scrollIntoView({behavior:'smooth',block:'start'});
        }
      });
    });

    // Simple sample analytics hook (no external calls)
    window.trackEvent = function(name, data){
      try{console.log('track',name,data||{});}catch(e){}
    };

    // Accessibility: allow escape to close mobile nav
    document.addEventListener('keydown', function(e){
      if(e.key==='Escape' && nav && window.innerWidth < 880){
        nav.style.display='none';
      }
    });
  });
})();"} 
